package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="aetheris_paper_risk_policy") public class PaperRiskPolicyEntity {@Id @Column(length=80) private String profileKey;private int maxOpenPositions;private double maxGrossExposureMultiple;private double maxSymbolExposurePct;private double maxCorrelatedExposurePct;private int maxStaleDataSeconds;@Column(nullable=false) private Instant updatedAt;protected PaperRiskPolicyEntity(){}public PaperRiskPolicyEntity(String key){this.profileKey=key;update(new PaperRiskPolicyRequest(3,3,40,82,120));}public void update(PaperRiskPolicyRequest r){this.maxOpenPositions=Math.max(1,Math.min(r.maxOpenPositions(),20));this.maxGrossExposureMultiple=Math.max(.25,Math.min(r.maxGrossExposureMultiple(),10));this.maxSymbolExposurePct=Math.max(5,Math.min(r.maxSymbolExposurePct(),100));this.maxCorrelatedExposurePct=Math.max(10,Math.min(r.maxCorrelatedExposurePct(),100));this.maxStaleDataSeconds=Math.max(5,Math.min(r.maxStaleDataSeconds(),3600));this.updatedAt=Instant.now();}public String getProfileKey(){return profileKey;}public int getMaxOpenPositions(){return maxOpenPositions;}public double getMaxGrossExposureMultiple(){return maxGrossExposureMultiple;}public double getMaxSymbolExposurePct(){return maxSymbolExposurePct;}public double getMaxCorrelatedExposurePct(){return maxCorrelatedExposurePct;}public int getMaxStaleDataSeconds(){return maxStaleDataSeconds;}public Instant getUpdatedAt(){return updatedAt;}}
